### [ ] M1-S1 — Supabase project, schema, and RLS

**Goal:** Create the database tables and access policies that every later slice depends on.

**Build prompt:**
```
In the Supabase dashboard (https://supabase.com) create a new project called "formcoach".
Save your project URL and anon key — you will need them in M1-S2.

Open the SQL Editor and run all of the following in one script:

-- ── 1. MEMBERS ──────────────────────────────────────────────────────────────
create table public.members (
  id           uuid primary key references auth.users(id) on delete cascade,
  display_name text not null default '',
  created_at   timestamptz not null default now()
);
alter table public.members enable row level security;
create policy "member reads own row"    on public.members for select using (auth.uid() = id);
create policy "member inserts own row"  on public.members for insert with check (auth.uid() = id);
create policy "member updates own row"  on public.members for update using (auth.uid() = id);

-- ── 2. MEASUREMENTS (sensitive — kept separate to ease auditing) ─────────────
create table public.measurements (
  id          bigint generated always as identity primary key,
  member_id   uuid not null references public.members(id) on delete cascade,
  measured_at date not null default current_date,
  weight_kg   numeric,
  chest_cm    numeric,
  waist_cm    numeric,
  hips_cm     numeric,
  notes       text
);
alter table public.measurements enable row level security;
create policy "member reads own measurements"   on public.measurements for select
  using  (auth.uid() = member_id);
create policy "member inserts own measurements" on public.measurements for insert
  with check (auth.uid() = member_id);
create policy "member updates own measurements" on public.measurements for update
  using (auth.uid() = member_id);
create policy "member deletes own measurements" on public.measurements for delete
  using (auth.uid() = member_id);

-- ── 3. WORKOUTS ──────────────────────────────────────────────────────────────
create table public.workouts (
  id          bigint generated always as identity primary key,
  member_id   uuid not null references public.members(id) on delete cascade,
  week_number int  not null,
  day_number  int  not null check (day_number between 1 and 7),
  title       text not null,
  notes       text,
  created_at  timestamptz not null default now()
);
alter table public.workouts enable row level security;
create policy "member reads own workouts"   on public.workouts for select
  using (auth.uid() = member_id);
create policy "member inserts own workouts" on public.workouts for insert
  with check (auth.uid() = member_id);
create policy "member updates own workouts" on public.workouts for update
  using (auth.uid() = member_id);
create policy "coach manages all workouts"  on public.workouts for all
  using      ((select role from public.roles where id = auth.uid()) = 'coach')
  with check ((select role from public.roles where id = auth.uid()) = 'coach');

-- ── 4. SETS ──────────────────────────────────────────────────────────────────
create table public.sets (
  id            bigint generated always as identity primary key,
  workout_id    bigint not null references public.workouts(id) on delete cascade,
  member_id     uuid   not null references public.members(id) on delete cascade,
  exercise_name text   not null,
  planned_reps  int,
  actual_reps   int,
  weight_kg     numeric,
  completed     boolean not null default false,
  created_at    timestamptz not null default now()
);
alter table public.sets enable row level security;
create policy "member reads own sets"   on public.sets for select using (auth.uid() = member_id);
create policy "member inserts own sets" on public.sets for insert with check (auth.uid() = member_id);
create policy "member updates own sets" on public.sets for update using (auth.uid() = member_id);
create policy "coach manages all sets"  on public.sets for all
  using      ((select role from public.roles where id = auth.uid()) = 'coach')
  with check ((select role from public.roles where id = auth.uid()) = 'coach');

-- ── 5. VIDEOS (private — members never see each other's videos) ───────────────
create table public.videos (
  id            bigint generated always as identity primary key,
  member_id     uuid   not null references public.members(id) on delete cascade,
  workout_id    bigint references public.workouts(id) on delete set null,
  storage_path  text   not null,
  feedback_text text,
  checked_at    timestamptz,
  created_at    timestamptz not null default now()
);
alter table public.videos enable row level security;
-- Videos: member-only access. Coaches have NO access. No "coach manages all videos" policy.
create policy "member reads own videos"   on public.videos for select using (auth.uid() = member_id);
create policy "member inserts own videos" on public.videos for insert with check (auth.uid() = member_id);

-- ── 6. SUBSCRIPTIONS ─────────────────────────────────────────────────────────
create table public.subscriptions (
  id                     bigint generated always as identity primary key,
  member_id              uuid not null references public.members(id) on delete cascade,
  revenuecat_customer_id text not null,
  status                 text not null default 'inactive'
    check (status in ('active','inactive','past_due')),
  plan_id                text,
  expires_at             timestamptz,
  updated_at             timestamptz not null default now(),
  unique (member_id)
);
alter table public.subscriptions enable row level security;
-- App can read its own subscription to show status. Only the webhook writes this table.
create policy "member reads own subscription" on public.subscriptions for select
  using (auth.uid() = member_id);

-- ── 7. ROLES (server-only — NO member select policy intentionally) ───────────
create table public.roles (
  id   uuid primary key references auth.users(id) on delete cascade,
  role text not null default 'member' check (role in ('member','coach'))
);
alter table public.roles enable row level security;
-- Deliberately no SELECT policy. The roles table can only be read via the service role
-- (Edge Functions). Members cannot query their own role from the app.

-- ── 8. FORM CHECK USAGE (rate-limit counter — 5 checks per member per day) ───
create table public.form_check_usage (
  id          bigint generated always as identity primary key,
  member_id   uuid not null references public.members(id) on delete cascade,
  check_date  date not null default current_date,
  count       int  not null default 0,
  unique (member_id, check_date)
);
alter table public.form_check_usage enable row level security;
-- Members can read their own usage count (so the UI can show "X of 5 used today").
-- Only Edge Functions write to this table.
create policy "member reads own usage" on public.form_check_usage for select
  using (auth.uid() = member_id);

-- ── 9. STORAGE BUCKET ────────────────────────────────────────────────────────
-- In the Supabase dashboard → Storage → New bucket:
--   Name:   videos
--   Public: OFF (private bucket — this is critical)
--
-- Then in Storage → Policies, add these two policies on storage.objects
-- scoped to the "videos" bucket:
--
--   Policy 1 — INSERT
--   Name: "member uploads to own folder"
--   Operation: INSERT
--   USING: auth.uid()::text = (storage.foldername(name))[1]
--
--   Policy 2 — SELECT
--   Name: "member reads own folder"
--   Operation: SELECT
--   USING: auth.uid()::text = (storage.foldername(name))[1]
--
-- This means every file must be stored at path: videos/{member_id}/{filename}
-- A member cannot read another member's files.
```

**How to test:**
- Supabase Table Editor shows all eight tables.
- Authentication → Policies shows RLS is ON and policies are listed for each table.
- Storage shows a private "videos" bucket.

**Done when:**
- All eight tables exist with RLS enabled.
- Every policy above is present.
- Private "videos" bucket exists with two storage policies.

