### [ ] M1-S4 — Sign-in screen, auth context, and routing

**Goal:** Existing members sign in; the app routes to the tab navigator when signed in and back to auth when signed out; sessions survive app restarts.

**Build prompt:**
```
Create src/hooks/useAuth.ts:

import React, { createContext, useContext, useEffect, useState } from 'react';
import { Session } from '@supabase/supabase-js';
import { supabase } from '../lib/supabase';

type AuthContextType = {
  session: Session | null;
  loading: boolean;
};

const AuthContext = createContext<AuthContextType>({ session: null, loading: true });

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (event, session) => {
        setSession(session);
        // After any sign-in, ensure a members row exists.
        if (event === 'SIGNED_IN' && session?.user) {
          await supabase.from('members').upsert(
            { id: session.user.id,
              display_name: session.user.email?.split('@')[0] ?? '' },
            { onConflict: 'id' }
          );
        }
      }
    );
    return () => subscription.unsubscribe();
  }, []);

  return (
    <AuthContext.Provider value={{ session, loading }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}

──────────────────────────────────────────────────────────────────────────────

Create src/screens/SignInScreen.tsx. Use only these exact token values:

Layout (identical token values to SignUpScreen):
