Create an Edge Function "get-role" to read the user's role server-side
(the roles table has no client-accessible SELECT policy):

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
const supabase = createClient(
  Deno.env.get('SUPABASE_URL')!,
  Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
);
Deno.serve(async (req) => {
  const auth = req.headers.get('Authorization');
  if (!auth) return new Response('Unauthorized', { status: 401 });
  const { data: { user } } = await supabase.auth.getUser(auth.replace('Bearer ',''));
  if (!user) return new Response('Unauthorized', { status: 401 });
  const { data } = await supabase.from('roles').select('role').eq('id', user.id).maybeSingle();
  return new Response(JSON.stringify({ role: data?.role ?? 'member' }),
    { headers: { 'Content-Type': 'application/json' } });
});

